/**
 * Shared staging hygiene for machine-local fa/dmtools runtime artifacts (gh-628, gh-683).
 *
 * The machine's runtime files live INSIDE the committed .dmtools/ directory
 * (config.js, runners/), so the directory itself cannot be ignored — each
 * artifact is excluded by pathspec instead. Every commit-producing staging
 * site (developTicketAndCreatePR, developBugAndCreatePR, pushReworkChanges,
 * timerAutoCommitAndSave) builds its commands from this single canonical
 * list, so the `git rm -r --cached` untrack list and the `git add` exclusion
 * pathspecs can never drift apart again (round 1 review found .dmtools/
 * fa-sessions in every staging pathspec but in none of the untrack lists).
 *
 * gh-683 (live fa run 37153405587, fa gh-1206, 2026-10-03): `git add` runs
 * its ignored-pathspec guard on EVERY pathspec element — including `:!`
 * EXCLUSION pathspecs. Naming a path that is gitignored AND exists untracked
 * in the working tree fails the whole add with exit 1 ("The following paths
 * are ignored by one of your .gitignore files ... Use -f if you really want
 * to add them"), killing the dev leg after a fully green run. The guard does
 * NOT fire when the ignored path is tracked (poisoned branch), nonexistent,
 * or when the pathspec is a glob — only for a literal pathspec naming an
 * existing ignored-untracked file. So the staging pathspecs are now built
 * through a `git check-ignore` probe (buildStagingPathspecs): a path git
 * already ignores is left to git's own exclude machinery (gitignore alone
 * keeps `git add .` away from it — no pathspec, no guard to trip), while a
 * path git does NOT ignore keeps its `:!` exclusion (and a not-ignored path
 * can never trip the ignored-files guard). This holds for ANY future runtime
 * file added to the list: ignored repo → no pathspec; unignored repo →
 * exclusion, guard-safe either way.
 *
 * GraalJS-compatible: var/plain functions only, no Node APIs.
 */

var RUNTIME_ARTIFACT_PATHS = [
    '.dmtools/copilot-sessions',
    '.dmtools/credential-helper.log',
    '.dmtools/fa-trace.log',
    '.dmtools/run-output.txt',
    '.dmtools/stall-capture.log',
    '.dmtools/fa-sessions',
    '.dmtools-session-output.log',
    '.claude-session-id'
];

/**
 * Command that lists which runtime artifacts git actually TRACKS (gh-683: only tracked paths are ever
 * handed to `git rm`). A plain `git ls-files -- <paths>` — no pipe, `;` or `&&` — so it passes the
 * Java cli_execute_command shell-injection validator (epam/dm.ai#679: the old single-line
 * `ls-files | while read … git rm` form was rejected there on every run).
 */
function buildTrackedArtifactsCommand() {
    return 'git ls-files -- ' + RUNTIME_ARTIFACT_PATHS.join(' ');
}

/**
 * `git rm --cached` for an explicit list of tracked paths (`--cached` is required — plain `git rm`
 * refuses locally-modified files, and these logs are always being appended). Paths are quoted.
 */
function buildUntrackPathsCommand(paths) {
    return 'git rm -r --cached --ignore-unmatch -- ' + (paths || []).map(function (p) {
        return '"' + p + '"';
    }).join(' ');
}

/**
 * Untracks already-poisoned runtime artifacts: lists the tracked ones, then removes only those from
 * the index. Nothing tracked (the normal case) = exactly ONE command (the listing) and no rm, so an
 * untracked path is never named to `git rm`. Two plain commands instead of one shell pipeline, so the
 * same code runs under the Java validator and the Dart bridge.
 *
 * @param {function(string): *} run executes a command string (the site's own wrapper, in the right
 *        working directory) and returns its output; may throw — callers keep their own try/catch
 * @returns {string[]} the paths that were untracked (empty when nothing was tracked)
 */
function untrackRuntimeArtifacts(run) {
    var listed = String(run(buildTrackedArtifactsCommand()) || '');
    var tracked = listed.split(/\r?\n/).map(function (l) { return l.trim(); }).filter(function (l) {
        return l && RUNTIME_ARTIFACT_PATHS.some(function (a) { return l === a || l.indexOf(a + '/') === 0; });
    });
    if (tracked.length === 0) return [];
    run(buildUntrackPathsCommand(tracked));
    return tracked;
}

/**
 * Probe-filtered `:!` exclusion pathspecs for an arbitrary path list.
 * Each path that git does NOT already ignore yields `":!<path>"` plus
 * `":!<path>/**"` (quoted, so a shell or cli_execute_command never splits
 * paths); a path git already ignores yields nothing — gitignore alone keeps
 * it out of `git add`, and naming it in ANY pathspec (exclusions included)
 * is exactly what trips git add's ignored-pathspec guard.
 *
 * gh-683 + gh-1164 probe contract: `runCommand` takes { command } (e.g. the
 * site's cli_execute_command wrapper, executing in the SAME working
 * directory as the add) and runs `git check-ignore -q -- <path>`:
 *   - probe succeeds (exit 0 = git already ignores the path): the exclusion
 *     is DROPPED (live guard casualties: fa runs 37153405587, 37153882406);
 *   - probe throws (exit 1 = not ignored; cli_execute_command throws on any
 *     non-zero exit): the exclusion is KEPT — the pathspec is the only thing
 *     keeping the path out of the commit, and a not-ignored path can never
 *     trip the ignored-files guard.
 * Without `runCommand` the full static exclusion list is returned
 * (pre-gh-683 behavior) — kept for signature compatibility.
 */
function buildExclusionPathspecs(paths, runCommand) {
    var kept = paths || [];
    if (typeof runCommand === 'function') {
        kept = kept.filter(function (path) {
            try {
                runCommand({ command: 'git check-ignore -q -- ' + path });
                return false; // ignored — git's own exclude machinery owns it
            } catch (e) {
                return true; // not ignored (or probe unavailable) — pathspec exclusion required
            }
        });
    }
    var specs = [];
    for (var i = 0; i < kept.length; i++) {
        specs.push('":!' + kept[i] + '"');
        specs.push('":!' + kept[i] + '/**"');
    }
    return specs.join(' ');
}

/**
 * `:!` pathspec exclusions (each path and its contents) for `git add` staging
 * commands, e.g. `git add . -- <specs>`. Quoted, so a shell (or
 * cli_execute_command) never splits paths.
 *
 * `extraPaths` (gh-1164): site-specific excludes appended beside the runtime
 * artifacts — above all `factory-kit`, the factory workflow's nested
 * machine-infra repo. Live fa gh-1164 (runs 37153882406 + 37220167230,
 * 2026-10-03/04): the timer autosave's `git add -A` FAILED every 5 minutes
 * for 40+ minutes with exit 1 "The following paths are ignored by one of
 * your .gitignore files", the dev agent's real work was never committed and
 * died with the runner — because every site appended
 * `":!factory-kit" ":!factory-kit/**"` STATICALLY, after the probe-filtered
 * runtime specs. Scratch-repo repro (git 2.50.1): the guard fires on ANY
 * literal pathspec — exclusions included — naming an existing,
 * gitignored-untracked path, and a runner workspace has exactly that when
 * `factory-kit` is materialized AND gitignored. Extra paths therefore go
 * through the SAME check-ignore probe: ignored+present → exclusion dropped
 * (gitignore keeps it out); not ignored (the nested-gitlink case the
 * exclusion exists for) → exclusion kept, guard-safe either way.
 *
 * Every staging site runs the untrack command BEFORE the add, so the probe
 * observes the post-untrack state: a poisoned branch's tracked runtime files
 * are already index-less by then, and the tracked+ignored case never trips
 * the guard anyway.
 */
function buildStagingPathspecs(runCommand, extraPaths) {
    var paths = RUNTIME_ARTIFACT_PATHS.concat(extraPaths || []);
    return buildExclusionPathspecs(paths, runCommand);
}

/**
 * True when a `git status --porcelain` line only reports a machine-local
 * runtime artifact (untracked leftover of the `--cached` untrack, or a dirty
 * log). Such lines are never the CLI agent's work and must not flip
 * change-detection checks (gh-628 round 1: developBugAndCreatePR's
 * interrupted-agent recovery fired on every leg and posted a false
 * "Partial anal…

/**
 * Unit tests for js/common/gitStaging.js — the single source of truth for
 * machine-local runtime-artifact staging hygiene (gh-628).
 *
 * gh-628 live case: the machine's runtime logs live INSIDE the committed
 * .dmtools/ directory (config.js, runners/), so the directory itself cannot
 * be ignored; the timer's broad `git add` swept .dmtools/credential-helper.log
 * (the credential helper's serving trace) into three ticket-branch commits.
 * Every commit-producing staging site must derive its `git rm -r --cached`
 * untrack list and its `git add` exclusion pathspecs from the SAME canonical
 * list so the two can never drift apart again (the first review round found
 * .dmtools/fa-sessions present in staging exclusions but missing from all
 * four untrack lists).
 */

var gitStaging = loadModule('js/common/gitStaging.js');

var ALL_ARTIFACTS = [
    '.dmtools/copilot-sessions',
    '.dmtools/credential-helper.log',
    '.dmtools/fa-trace.log',
    '.dmtools/run-output.txt',
    '.dmtools/stall-capture.log',
    '.dmtools/fa-sessions',
    '.dmtools-session-output.log',
    '.claude-session-id'
];

suite('gitStaging', function() {

    test('canonical artifact list covers every machine-local runtime path (gh-628)', function() {
        assert.deepEqual(gitStaging.RUNTIME_ARTIFACT_PATHS, ALL_ARTIFACTS,
            'shared list must contain every runtime artifact (incl. .dmtools/fa-sessions)');
    });

    test('untrack commands contain no shell metacharacters the Java validator rejects (epam/dm.ai#679)', function() {
        var list = gitStaging.buildTrackedArtifactsCommand();
        var rm = gitStaging.buildUntrackPathsCommand(['.dmtools/fa-trace.log']);
        [list, rm].forEach(function(cmd) {
            ['|', ';', '&&', '||', '`', '$(', '${', '>', '<', '\n'].forEach(function(bad) {
                assert.equal(cmd.indexOf(bad), -1, JSON.stringify(cmd) + ' contains ' + JSON.stringify(bad));
            });
        });
        assert.ok(list.indexOf('git ls-files -- ') === 0, 'candidates are enumerated through git ls-files (gh-683)');
        for (var i = 0; i < ALL_ARTIFACTS.length; i++) {
            assert.contains(list, ' ' + ALL_ARTIFACTS[i], 'untrack candidate list must cover ' + ALL_ARTIFACTS[i]);
        }
        assert.contains(rm, 'git rm -r --cached --ignore-unmatch -- "\.dmtools/fa-trace.log"'.replace('\\.', '.'),
            'the rm stays --cached and --ignore-unmatch, paths quoted');
    });

    test('untrackRuntimeArtifacts: nothing tracked = ONE command, no git rm (gh-683 no-op)', function() {
        var seen = [];
        var removed = gitStaging.untrackRuntimeArtifacts(function(c) { seen.push(c); return ''; });
        assert.deepEqual(removed, []);
        assert.equal(seen.length, 1);
        assert.ok(seen[0].indexOf('git ls-files -- ') === 0);
    });

    test('untrackRuntimeArtifacts: only TRACKED artifacts are handed to git rm; foreign paths are ignored', function() {
        var seen = [];
        var removed = gitStaging.untrackRuntimeArtifacts(function(c) {
            seen.push(c);
            return c.indexOf('git ls-files') === 0
                ? '.dmtools/credential-helper.log\n.dmtools/fa-sessions/a/b.json\nsrc/not-an-artifact.txt\n'
                : '';
        });
        assert.deepEqual(removed, ['.dmtools/credential-helper.log', '.dmtools/fa-sessions/a/b.json']);
        assert.equal(seen.length, 2);
        assert.contains(seen[1], '"' + '.dmtools/credential-helper.log' + '"');
        assert.equal(seen[1].indexOf('not-an-artifact'), -1, 'a path outside the artifact list is never removed');
    });

    test('untrackRuntimeArtifacts: a failing listing propagates (callers keep their try/catch)', function() {
        assert.throws(function() {
            gitStaging.untrackRuntimeArtifacts(function() { throw new Error('git failed'); });
        }, /git failed/);
    });

    test('buildStagingPathspecs excludes every artifact, file and directory-content', function() {
        var specs = gitStaging.buildStagingPathspecs();
        for (var i = 0; i < ALL_ARTIFACTS.length; i++) {
            assert.contains(specs, '":!' + ALL_ARTIFACTS[i] + '"',
                'staging pathspec must exclude ' + ALL_ARTIFACTS[i]);
            assert.contains(specs, '":!' + ALL_ARTIFACTS[i] + '/**"',
                'staging pathspec must exclude ' + ALL_ARTIFACTS[i] + '/**');
        }
    });

    test('buildStagingPathspecs(runner): paths git ALREADY ignores are never named — gh-683 ignored-pathspec guard', function() {
        // Live fa run 37153405587 (fa gh-1206, 2026-10-03): `git add` runs its
        // ignored-pathspec guard on `:!` EXCLUSION pathspecs too — naming a
        // path that is gitignored and exists untracked kills the whole add
        // with exit 1 ("The following paths are ignored ... Use -f if you
        // really want to add them"). A repo whose .gitignore covers the
        // runtime artifacts must therefore produce staging specs WITHOUT
        // them: gitignore alone keeps `git add .` away.
        var probeCalls = [];
        var allIgnored = gitStaging.buildStagingPathspecs(function (args) {
            probeCalls.push(args.command);
            return ''; // check-ignore exit 0 = ignored — no throw
        });
        assert.equal(allIgnored, '',
            'a repo that ignores every artifact needs no runtime pathspec at all');
        assert.equal(probeCalls.length, ALL_ARTIFACTS.length,
