{
  "key": "pr-900",
  "fields": {
    "summary": "fix(claude): stale .claude-session-id no longer fails the run (#898)",
    "description": "Fixes #898.\n1. claude.sh: when the resumed run fails with 'No conversation found with session ID', delete .claude-session-id and retry ONCE without --resume (full prompt). Any other failure is not retried and keeps its exit code.\n2. .claude-session-id is added to the runtime artifacts that auto-save/commit staging excludes and untracks, so a session id no longer travels through git.\nTests: stale-session case (2 claude calls, retry has no --resume, id replaced, exit 0) fails on the old script; non-stale failure keeps exit 1 and is not retried; gitStaging 11/11."
  }
}

/**
 * Shared staging hygiene for machine-local fa/dmtools runtime artifacts (gh-628, gh-683).
 *
 * The machine's runtime files live INSIDE the committed .dmtools/ directory
 * (config.js, runners/), so the directory itself cannot be ignored — each
 * artifact is excluded by pathspec instead. Every commit-producing staging
 * site (developTicketAndCreatePR, developBugAndCreatePR, pushReworkChanges,
 * timerAutoCommitAndSave) builds its commands from this single canonical
 * list, so the `git rm -r --cached` untrack list and the `git add` exclusion
 * pathspecs can never drift apart again (round 1 review found .dmtools/
 * fa-sessions in every staging pathspec but in none of the untrack lists).
 *
 * gh-683 (live fa run 37153405587, fa gh-1206, 2026-10-03): `git add` runs
 * its ignored-pathspec guard on EVERY pathspec element — including `:!`
 * EXCLUSION pathspecs. Naming a path that is gitignored AND exists untracked
 * in the working tree fails the whole add with exit 1 ("The following paths
 * are ignored by one of your .gitignore files ... Use -f if you really want
 * to add them"), killing the dev leg after a fully green run. The guard does
 * NOT fire when the ignored path is tracked (poisoned branch), nonexistent,
 * or when the pathspec is a glob — only for a literal pathspec naming an
 * existing ignored-untracked file. So the staging pathspecs are now built
 * through a `git check-ignore` probe (buildStagingPathspecs): a path git
 * already ignores is left to git's own exclude machinery (gitignore alone
 * keeps `git add .` away from it — no pathspec, no guard to trip), while a
 * path git does NOT ignore keeps its `:!` exclusion (and a not-ignored path
 * can never trip the ignored-files guard). This holds for ANY future runtime
 * file added to the list: ignored repo → no pathspec; unignored repo →
 * exclusion, guard-safe either way.
 *
 * GraalJS-compatible: var/plain functions only, no Node APIs.
 */

var RUNTIME_ARTIFACT_PATHS = [
    '.dmtools/copilot-sessions',
    '.dmtools/credential-helper.log',
    '.dmtools/fa-trace.log',
    '.dmtools/run-output.txt',
    '.dmtools/stall-capture.log',
    '.dmtools/fa-sessions',
    '.dmtools-session-output.log',
    '.claude-session-id'
];

/**
 * Command that lists which runtime artifacts git actually TRACKS (gh-683: only tracked paths are ever
 * handed to `git rm`). A plain `git ls-files -- <paths>` — no pipe, `;` or `&&` — so it passes the
 * Java cli_execute_command shell-injection validator (epam/dm.ai#679: the old single-line
 * `ls-files | while read … git rm` form was rejected there on every run).
 */
function buildTrackedArtifactsCommand() {
    return 'git ls-files -- ' + RUNTIME_ARTIFACT_PATHS.join(' ');
}

/**
 * `git rm --cached` for an explicit list of tracked paths (`--cached` is required — plain `git rm`
 * refuses locally-modified files, and these logs are always being appended). Paths are quoted.
 */
function buildUntrackPathsCommand(paths) {
    return 'git rm -r --cached --ignore-unmatch -- ' + (paths || []).map(function (p) {
        return '"' + p + '"';
    }).join(' ');
}

/**
 * Untracks already-poisoned runtime artifacts: lists the tracked ones, then removes only those from
 * the index. Nothing tracked (the normal case) = exactly ONE command (the listing) and no rm, so an
 * untracked path is never named to `git rm`. Two plain commands instead of one shell pipeline, so the
 * same code runs under the Java validator and the Dart bridge.
 *
 * @param {function(string): *} run executes a command string (the site's own wrapper, in the right
 *        working directory) and returns its output; may throw — callers keep their own try/catch
 * @returns {string[]} the paths that were untracked (empty when nothing was tracked)
 */
function untrackRuntimeArtifacts(run) {
    var listed = String(run(buildTrackedArtifactsCommand()) || '');
    var tracked = listed.split(/\r?\n/).map(function (l) { return l.trim(); }).filter(function (l) {
        return l && RUNTIME_ARTIFACT_PATHS.some(function (a) { return l === a || l.indexOf(a + '/') === 0; });
    });
